fn size(xs: List[Int]) -> Int
  requires (len(xs) >= 0)
  ensures (result == len(xs))
  effects pure
  example (size([]) == 0)
  example (size([4, 4]) == 2)
{
  match xs { [] => 0 [_, ..t] => (1 + size(t)) }
}

fn tally(xs: List[Int], v: Int) -> Int
  requires (len(xs) >= 0)
  ensures (result == count(xs, v))
  effects pure
  example (tally([3, 1, 3, 3], 3) == 3)
  example (tally([], 3) == 0)
{
  match xs { [] => 0 [h, ..t] => if (h == v) then (1 + tally(t, v)) else tally(t, v) }
}

fn pick(xs: List[Int], cands: List[Int]) -> Option[Int]
  requires (len(xs) >= 0)
  ensures match result { None => forall x in cands: ((2 * count(xs, x)) <= len(xs)) Some(v) => ((2 * count(xs, v)) > len(xs)) }
  effects pure
  example (pick([3, 1, 3, 3], [3, 1, 3, 3]) == Some(3))
  example (pick([1, 2], [1, 2]) == None)
  example (pick([], []) == None)
{
  match cands { [] => None [h, ..t] => if ((2 * tally(xs, h)) > size(xs)) then Some(h) else pick(xs, t) }
}

fn majority(xs: List[Int]) -> Option[Int]
  requires (len(xs) >= 0)
  ensures match result { None => forall x in xs: ((2 * count(xs, x)) <= len(xs)) Some(v) => ((2 * count(xs, v)) > len(xs)) }
  effects pure
  example (majority([3, 1, 3, 3]) == Some(3))
  example (majority([1, 2]) == None)
  example (majority([]) == None)
  example (majority([5]) == Some(5))
{
  pick(xs, xs)
}

