  ensures not contains(result, v)
  ensures forall x in xs: ((x == v) or contains(result, x))
  effects pure
  example (without([3, 9, 1], 9) == [3, 1])
  example (without([4], 4) == [])
{
  match xs { [] => [] [h, ..t] => if (h == v) then t else ([h] ++ without(t, v)) }
}

fn is_max(xs: List[Int], o: Option[Int]) -> Bool
  requires distinct(xs)
  ensures ((not result) or distinct(xs))
  effects pure
  example (is_max([3, 9, 1], Some(9)) == true)
  example (is_max([3, 9, 1], Some(3)) == false)
  example (is_max([], None) == true)
{
  match o { None => is_empty(xs) Some(m) => (has(xs, m) and (count_greater(xs, m) == 0)) }
}

fn is_second(xs: List[Int], o: Option[Int]) -> Bool
  requires distinct(xs)
  ensures ((not result) or distinct(xs))
  effects pure
  example (is_second([3, 9, 1], Some(3)) == true)
  example (is_second([3, 9, 1], Some(9)) == false)
  example (is_second([4], None) == true)
{
  match o { None => short(xs) Some(s) => (has(xs, s) and (count_greater(xs, s) == 1)) }
}

fn max_of(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures is_max(xs, result)
  effects pure
  example (max_of([3, 9, 1]) == Some(9))
  example (max_of([]) == None)
{
  match xs { [] => None [h, ..t] => match max_of(t) { None => Some(h) Some(m) => if (h > m) then Some(h) else Some(m) } }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures is_second(xs, result)
  effects pure
  example (second_largest([3, 9, 1]) == Some(3))
  example (second_largest([4]) == None)
  example (second_largest([]) == None)
  example (second_largest([5, 2]) == Some(2))
{
  match max_of(xs) { None => None Some(m) => max_of(without(xs, m)) }
}

fn is_empty(xs: List[Int]) -> Bool
  requires distinct(xs)
  ensures (result == (len(xs) == 0))
  effects pure
  example (is_empty([]) == true)
  example (is_empty([4]) == false)
{
  match xs { [] => true [_, ..t] => false }
}

fn short(xs: List[Int]) -> Bool
  requires distinct(xs)
  ensures (result == (len(xs) < 2))
  effects pure
  example (short([]) == true)
  example (short([4]) == true)
  example (short([3, 9, 1]) == false)
{
  match xs { [] => true [_, ..t] => is_empty(t) }
}

fn has(xs: List[Int], v: Int) -> Bool
  requires distinct(xs)
  ensures (result == contains(xs, v))
  effects pure
  example (has([3, 9, 1], 9) == true)
  example (has([3, 9, 1], 4) == false)
{
  match xs { [] => false [h, ..t] => ((h == v) or has(t, v)) }
}

fn count_greater(xs: List[Int], s: Int) -> Int
  requires distinct(xs)
  ensures (result == (count x in xs: (x > s)))
  effects pure
  example (count_greater([3, 9, 1], 2) == 2)
  example (count_greater([3, 9, 1], 9) == 0)
{
  match xs { [] => 0 [h, ..t] => if (h > s) then (1 + count_greater(xs, s)) else count_greater(t, s) }
}

